examples.code:
At-most-once:   poll -> commit offset -> process        (crash after commit: message lost)
At-least-once:  poll -> process -> commit offset        (crash before commit: processed again)

# Producer defaults since Kafka 3.0
enable.idempotence=true     # retries do not create duplicates in the log
acks=all                    # written to all in-sync replicas

// Idempotent consumer
@Transactional
@KafkaListener(topics = "orders")
void onOrderPlaced(OrderPlaced e) {
    if (!processed.register(e.eventId())) return;     // UNIQUE(event_id)
    invoices.create(e.orderId(), e.total());
}

@Bean
DefaultErrorHandler errorHandler(KafkaTemplate<Object, Object> template) {
    var recoverer = new DeadLetterPublishingRecoverer(template);    // -> orders.DLT
    var backOff = new ExponentialBackOffWithMaxRetries(4);
    backOff.setInitialInterval(500);
    backOff.setMultiplier(2.0);
    var handler = new DefaultErrorHandler(recoverer, backOff);
    handler.addNotRetryableExceptions(ValidationException.class);   // straight to the DLT
    return handler;
}

// WRONG: a validation error retried 10 times with 30 s waits -> the partition is stuck for 5 minutes
new DefaultErrorHandler(new FixedBackOff(30_000L, 10));

// RIGHT: retry only transient errors; permanent ones go to the DLT at once
handler.addNotRetryableExceptions(ValidationException.class, JsonProcessingException.class);

// All events of order 42 -> same partition -> consumed in order
kafka.send("orders", "42", new OrderPlaced(...));
kafka.send("orders", "42", new OrderPaid(...));
kafka.send("orders", "42", new OrderCancelled(...));

// Different orders spread across partitions -> parallel
kafka.send("orders", "43", new OrderPlaced(...));

// WRONG for ordered events: the failed one is retried later, the next ones go ahead
@RetryableTopic(attempts = "4")
@KafkaListener(topics = "orders")
void on(OrderEvent e) { ... }

// RIGHT: blocking retries (DefaultErrorHandler) keep the partition in order,
// then the DLT for what still fails

# application.yml
spring:
  kafka:
    consumer:
      enable-auto-commit: false       # the container commits
      auto-offset-reset: earliest     # a new group reads from the start
    listener:
      ack-mode: manual

// Manual acknowledgement after the work is saved
@KafkaListener(topics = "orders")
void on(OrderPlaced e, Acknowledgment ack) {
    invoices.create(e.orderId(), e.total());
    ack.acknowledge();
}

// WRONG: acknowledged, then processed asynchronously
@KafkaListener(topics = "orders")
void on(OrderPlaced e, Acknowledgment ack) {
    ack.acknowledge();
    executor.submit(() -> invoices.create(e.orderId(), e.total()));   // crash here = lost
}

// RIGHT: process, then acknowledge (as above)

// Avro schema, version 2: a new optional field with a default — backward compatible
{
  "type": "record", "name": "OrderPlaced",
  "fields": [
    {"name": "orderId",  "type": "long"},
    {"name": "total",    "type": "string"},
    {"name": "currency", "type": "string", "default": "BRL"}
  ]
}

# The registry rejects an incompatible change (compatibility mode BACKWARD)
$ curl -X PUT http://schema-registry:8081/config/orders-value -d '{"compatibility":"BACKWARD"}' \
       -H "Content-Type: application/vnd.schemaregistry.v1+json"

// WRONG: v2 renames "total" to "amount"
{"orderId": 42, "amount": "99.90"}       // old consumers: total is null

// RIGHT: add, migrate consumers, remove later
{"orderId": 42, "total": "99.90", "amount": "99.90"}    // transition
// ... later: OrderPlaced v3 without "total"
